    /**
     * Method to retrieve the Publisher via PublisherFetchOneSummary
     * @param 	summary PublisherFetchOneSummary 
     * @return 	PublisherFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Publisher getPublisher( PublisherFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "PublisherFetchOneSummary arg cannot be null" );
    	
    	Publisher entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Publisher
        	// --------------------------------------
        	CompletableFuture<Publisher> futureEntity = queryGateway.query(new FindPublisherQuery( new LoadPublisherFilter( summary.getPublisherId() ) ), ResponseTypes.instanceOf(Publisher.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Publisher with id " + summary.getPublisherId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


